set
  title = '3-D Design (Foundation Year)',
  goal = '3-D Design (Foundation Year)',
  summary = '3-D Design (Foundation Year) studies how form, space, gravity, scale, structure, and viewer movement shape three-dimensional work. Students work with solid form, void, weight, density, volume, contour, and proportion; negative space, site, and installation; materials and their associations; cutting, joinery, and load-bearing stability; additive and subtractive processes; casting and molding; found objects, assemblage, and object meaning; surface and finish as conceptual decisions; research through maquettes and revision; critique, documentation, and presentation; and a final project that synthesizes form, material, space, concept, craft, and documentation.',
